// NewFieldTypeMutation creates a new mutation for the FieldType entity.
func NewFieldTypeMutation(c Config, op Op, opts ...FieldTypeMutationOption) *FieldTypeMutation {
	return entbuilder.NewMutation[FieldType, int](&c, op, fieldtypeDescriptor, opts...)
}

// WithFieldTypeID sets the ID field and old-value loader of the mutation.
// The getFunc callback fetches the old entity value for OldField support.
// If getFunc is nil, the old-value loader is not set (used by DeleteOneID).
func WithFieldTypeID(id int, getFunc func(context.Context, int) (*FieldType, error)) FieldTypeMutationOption {
	return func(m *FieldTypeMutation) {
		m.SetID(id)
		if getFunc != nil {
			m.SetOldValueLoader(func(ctx context.Context) (any, error) { return getFunc(ctx, id) })
		}
	}
}

// WithFieldType sets the old FieldType of the mutation.
func WithFieldType(node *FieldType) FieldTypeMutationOption {
	return func(m *FieldTypeMutation) {
		m.SetID(node.ID)
		m.SetOldValueLoader(func(context.Context) (any, error) { return node, nil })
	}
}

// WithFieldTypeIDsFunc sets the function used to query entity IDs.
func WithFieldTypeIDsFunc(fn func(context.Context, ...predicate.FieldType) ([]int, error)) FieldTypeMutationOption {
	return func(m *FieldTypeMutation) {
		m.SetIDsFunc(func(ctx context.Context, preds ...func(*sql.Selector)) ([]any, error) {
			ps := make([]predicate.FieldType, len(preds))
			for i, p := range preds {
				ps[i] = p
			}
			ids, err := fn(ctx, ps...)
			if err != nil {
				return nil, err
			}
			out := make([]any, len(ids))
			for i, id := range ids {
				out[i] = id
			}
			return out, nil
		})
	}
}
